import React, { useEffect, useRef, useState } from "react";
import { api } from "../utils/api";
import { motion, AnimatePresence } from "framer-motion";
import { Bot, Send, X, Sparkles } from "lucide-react";

export default function ChatBot() {
  const [open, setOpen] = useState(false);
  const [typing, setTyping] = useState(false);

  const [input, setInput] = useState("");

  const [messages, setMessages] = useState([
    {
      role: "bot",
      text: "👋 Hi! Mai CyberRaksha AI Bot hu. Scam ya fraud related help chahiye? बस message bhejo 🛡️"
    }
  ]);

  const boxRef = useRef(null);

  useEffect(() => {
    if (open && boxRef.current) {
      boxRef.current.scrollTop = boxRef.current.scrollHeight;
    }
  }, [messages, open]);

  async function send() {
    if (!input.trim()) return;

    const userText = input.trim();
    setInput("");

    setMessages((prev) => [...prev, { role: "user", text: userText }]);

    setTyping(true);
    try {
      const res = await api.post("/api/bot/chat", { message: userText });
      const reply = res.data.reply || "Sorry, I couldn't understand.";

      setMessages((prev) => [...prev, { role: "bot", text: reply }]);
    } catch (err) {
      setMessages((prev) => [
        ...prev,
        {
          role: "bot",
          text: "❌ Bot is offline right now. Please try again later."
        }
      ]);
    } finally {
      setTyping(false);
    }
  }

  return (
    <>
      {/* Floating Button */}
      <div className="fixed bottom-6 right-6 z-[9999]">
        <button
          onClick={() => setOpen(true)}
          className="rounded-full px-5 py-4 bg-gray-900 text-white shadow-lg font-bold flex items-center gap-2 hover:scale-[1.02] transition"
        >
          <Bot size={20} />
          Chat
          <Sparkles size={18} />
        </button>
      </div>

      {/* Chat Window */}
      <AnimatePresence>
        {open && (
          <motion.div
            initial={{ opacity: 0, y: 20, scale: 0.95 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 20, scale: 0.95 }}
            transition={{ duration: 0.25 }}
            className="fixed bottom-24 right-6 w-[360px] max-w-[92vw] bg-white border shadow-2xl rounded-3xl z-[9999]"
          >
            {/* Header */}
            <div className="p-4 border-b flex items-center justify-between">
              <div className="font-black flex items-center gap-2">
                <Bot size={18} />
                CyberRaksha AI
              </div>

              <button
                onClick={() => setOpen(false)}
                className="p-2 rounded-xl border hover:bg-gray-50"
              >
                <X size={18} />
              </button>
            </div>

            {/* Messages */}
            <div
              ref={boxRef}
              className="p-4 space-y-3 h-[340px] overflow-auto"
            >
              {messages.map((m, idx) => (
                <div
                  key={idx}
                  className={`flex ${
                    m.role === "user" ? "justify-end" : "justify-start"
                  }`}
                >
                  <div
                    className={`max-w-[85%] px-4 py-3 rounded-2xl text-sm whitespace-pre-wrap ${
                      m.role === "user"
                        ? "bg-gray-900 text-white"
                        : "bg-gray-100 text-gray-900"
                    }`}
                  >
                    {m.text}
                  </div>
                </div>
              ))}

              {typing && (
                <div className="flex justify-start">
                  <div className="px-4 py-3 rounded-2xl text-sm bg-gray-100 text-gray-900">
                    Typing...
                  </div>
                </div>
              )}
            </div>

            {/* Input */}
            <div className="p-4 border-t flex gap-2">
              <input
                className="flex-1 border rounded-2xl px-4 py-3"
                placeholder="Type your scam problem..."
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === "Enter") send();
                }}
              />

              <button
                onClick={send}
                disabled={typing}
                className="px-4 py-3 rounded-2xl bg-gray-900 text-white font-bold disabled:opacity-60"
              >
                <Send size={18} />
              </button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </>
  );
}
